import sys
from collections import deque
data = sys.stdin.read().split()
target, sb, n = int(data[0]), int(data[1]), int(data[2])
pos = list(map(int, data[3:3 + n]))
bat = list(map(int, data[3 + n:3 + 2 * n]))
# state: (station or -1 for the start, upgrade already used, multiplier at this station)
start = (-1, 0, 1)
dist = {start: 0}
q = deque([start])
best = -1
while q:
    st = q.popleft()
    i, u, m = st
    if i == -1:
        p, cap = 0, sb
    else:
        p, cap = pos[i], bat[i] * m
    if p + cap >= target:
        best = dist[st]
        break
    for j in range(n):
        if p < pos[j] <= p + cap:
            for ns in ([(j, u, 1)] + ([(j, 1, 2)] if u == 0 else [])):
                if ns not in dist:
                    dist[ns] = dist[st] + 1
                    q.append(ns)
print(best)

